{"actions":[{"action":"success_contract","contract":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet to 127.0.0.1:6665 reaches the guest login prompt, and leave it running.","required_artifacts":["A running QEMU process using /app/alpine.iso","A local TCP listener on 127.0.0.1:6665 forwarded to the guest console/login prompt"],"required_behaviors":["QEMU starts successfully in the background","Port 6665 is reachable via telnet from localhost","Connecting with telnet shows the guest login prompt","The VM remains running after readiness is confirmed"],"known_invalid_patterns":["Only proving the ISO file exists","Only starting QEMU without confirming the telnet-accessible login prompt","Only checking that port 6665 is open without verifying the guest prompt","Foreground-only execution that does not leave the VM running"],"verification_plan":["Inspect available tools and environment for QEMU/telnet support","Launch QEMU with a serial console exposed on localhost:6665 and run it in the background","Wait until the telnet endpoint is ready","Verify by connecting to 127.0.0.1:6665 and observing the login prompt"],"finalization_evidence_required":["Receipt-backed evidence of the QEMU launch command and background process start","Receipt-backed evidence that 127.0.0.1:6665 accepted a telnet connection","Receipt-backed evidence that the connection displayed the guest login prompt"],"notes":["Prerequisites like tool availability are not success by themselves; the functional telnet/login behavior is the target."]}},{"action":"plan_update","plan":{"objective":"Start /app/alpine.iso in QEMU in the background and make it reachable via telnet on 127.0.0.1:6665 until the login prompt appears.","current_focus":"Discover available tooling and launch QEMU with serial console forwarding to port 6665.","implementation_approach":"Inspect environment for qemu/telnet or equivalent tools, then start QEMU in the background with a serial TCP listener on localhost:6665 and wait for readiness.","validation_strategy":"Use receipt-backed command output to confirm the VM launch, the listening port, and the telnet-visible login prompt.","verification_strategy":"Connect to 127.0.0.1:6665 and capture the prompt text from the guest console.","known_bad_behavior":["Treating ISO existence or process start alone as success","Using a setup that does not expose a telnet-accessible login prompt","Stopping after a smoke check that does not show the prompt"],"evidence_gaps":["No confirmed QEMU invocation yet","No confirmed listener on 127.0.0.1:6665 yet","No confirmed login prompt yet"],"risks":["QEMU may be missing or require alternate invocation flags","The ISO may need specific boot parameters or console settings"],"next_steps":["Probe for qemu-system-x86_64 and telnet/nc availability","Launch the VM in the background","Verify telnet prompt readiness"],"required_before_finalization":["Receipt-backed evidence of launch","Receipt-backed evidence of telnet connectivity","Receipt-backed evidence of login prompt"],"notes":["Preserve the original objective over any surrogate readiness checks."]}}]}
